'use strict';
/*
 * AK Cluster ID8 - the iDrive app: MGU Styles' four styles (Toro, M Sport,
 * M Sport Plus and M Track Mode; waliworld's, modified for its owner's own
 * use) with AK Cluster Layouts' settings.
 *
 * An adapter between the MGU App Kit (kit/runtime/mgu.js) and the cluster
 * service (service.js, built from src/car/main.js), and the app's own
 * page. The service runs in the background: the platform starts the app
 * by itself ("autostart"), so the cluster comes back at every start once
 * turned on.
 *
 * The page, as AK Cluster Layouts': the design's picture, its state, what
 * each of its places shows and the designs to pick from, with the bar's
 * Cluster on / off and Logs (the codes to photograph, in the page's place
 * until Logs is pressed past the last). Settings is the kit's list, one
 * step at a time: on / off, the style and the skin at its top, then
 * General and the style in use's own (Toro, M Sport, M Sport Plus or
 * M Track). Skin (or the Car profile's): Classic, or iDrive 7 -
 * near-black, flat rows and the orange focus, as the head unit's own
 * screens.
 *
 * This file is staged as main.js by tools/stage-app.js; the kit's builder
 * makes it the package's app.js. Node 8.
 */
const mgu = require('./kit/mgu');
const Sheet = require('./kit/sheet');
const { withAlpha } = require('./kit/canvas');
const Service = require('./service.js');
const MGeom = require('./mgeom.js');
const TGeom = require('./tgeom.js');
const Theme = require('./theme.js');
const Previews = require('./previews.js');
/* Logs' codes and file: AK Cluster Layouts' logs.js, the same codes as its Logs (tools/decode_logs.py) */
const Logs = require('./logs.js');
const Panel = require('./panel.js');
const path = require('path');
/* the page's words in the app's language (the Store builds it in Korean): drawn as literal text, so they go through
   the kit's catalogue here; the cluster's own lettering stays as the styles have it */
let tr = (s) => String(s);
try { tr = require('./kit/i18n').t; } catch (e) { /* tools: English */ }
let Record = null;
try { Record = require('./kit/record'); } catch (e) { /* no pixel images: the designs' sketches */ }

/*
 * How often each interface is re-read. Notifications carry most readings,
 * but a car that does not notify a field leaves it on the poll - so the
 * gear, the g sensor and boost need a fast one or the cluster runs behind
 * (a 3 s poll showed the gear two shifts late on the car).
 */
const POLL_MS = {
    'de.bmw.infotainment.vehicle.CDS': 300,              // rpm, temperatures
    'de.bmw.infotainment.vehicle.Vehicle2': 300,         // speed
    'de.bmw.infrastructure.VehicleInformation': 250,     // the engaged gear
    'de.bmw.infotainment.vehicle.CDS2': 400,             // lateral / long. g
    'de.bmw.infotainment.drivingexcitement.FES': 500,    // boost, drive mode
    'de.bmw.infrastructure.VehicleCondition': 1000,
    'de.bmw.infotainment.MDrive': 2000,
    'de.bmw.infotainment.KombiIF': 5000,                 // range, fuel, odo
    'de.bmw.infrastructure.EnvironmentalInformation': 15000
};
const DEFAULT_POLL_MS = 3000;

/* The app's current settings as one plain object. */
function settingsOf(settings, spec) {
    const out = {};
    (spec.settings || []).forEach((s) => { out[s.key] = settings.get(s.key); });
    return out;
}

/* What the service needs from the head unit, from the kit's background context. */
function hostFor(bg) {
    return {
        log: {
            info: (m) => bg.log.info(m),
            warn: (m) => bg.log.warn(m)
        },
        settings: () => settingsOf(bg.settings, bg.spec),
        dataDir: bg.dataDir,
        onSettingsChanged: (fn) => bg.settings.onChange(fn),
        /*
         * The car's diagnostic link, for the readings the bus does not carry
         * (src/car/engine.js). It is
         * the kit's read-only one: anything but a read is refused before it
         * leaves the head unit. Made only when the service first needs it.
         */
        diag() {
            const { ReadOnlyDiag } = require('./kit/readonly-diag');
            const { DidReader } = require('./kit/dids');
            const link = new ReadOnlyDiag(bg.signals, bg.log);
            return { link, reader: new DidReader(link, { ecu: 0x12 }), ready: link.init() };
        },
        subscribe(signals, onValue) {
            Object.keys(signals).forEach((svc) => {
                const handlers = {};
                Object.keys(signals[svc]).forEach((field) => {
                    if (field.charAt(0) === '_') return;
                    handlers[field] = (v) => onValue(svc, field, v);
                });
                /* Notifications carry the readings; the poll only catches
                   any the head unit drops. */
                const pollMs = POLL_MS[svc] || DEFAULT_POLL_MS;
                Promise.resolve()
                    .then(() => bg.signals.watch(svc, '1', handlers, bg.log, { pollMs }))
                    .then((r) => { if (r && r.error) bg.log.warn('signals ' + svc + ': ' + r.error); })
                    .catch((e) => bg.log.warn('signals ' + svc + ': ' + e));
            });
        }
    };
}

/* ------------------------------------------------------------ the screen */

/* the page's colours, as the skin has them (useSkin) */
const SKINS = {
    classic: { INK: '#e8f0f6', DIM: '#8d9aa6', FAINT: '#55626e', RED: '#ff263d', CARD: '#121b25', FIELD: '#05090f',
               BG: '#070b11', LINE: '#18222e', R: 1 },
    /* the head unit's own screens: near-black, silver-grey words, the orange focus, square corners */
    idrive7: { INK: '#f4f3f2', DIM: '#b5b3b4', FAINT: '#7d7c81', RED: '#ff570c', CARD: '#0b0b0d', FIELD: '#060607',
               BG: '#030304', LINE: '#2c2b2f', R: 0 }
};
let INK, DIM, FAINT, RED, CARD, FIELD, BG, LINE, SK7 = false;
/* a corner's radius in the skin: as drawn (Classic), or nearly square (iDrive 7) */
const rad = (r) => (SK7 ? Math.min(r, 3) : r);
function useSkin(id) {
    const k = SKINS[id] || SKINS.classic;
    ({ INK, DIM, FAINT, RED, CARD, FIELD, BG, LINE } = k);
    SK7 = !k.R;
}
useSkin('classic');
/* iDrive 7: the focus gradient, a thin orange edge at its top and bottom */
function focus7(cv, x, y, w, h) {
    cv.gradientRect(x, y, w, h, [[0, '#743008'], [1, '#361303']]);
    cv.fillRect(x, y, w, 2, RED); cv.fillRect(x, y + h - 2, w, 2, RED);
}

function statusColour(status) {
    if (/^On the cluster/.test(status)) return '#3ddc84';
    if (/^Off/.test(status)) return DIM;
    return '#ffb020';
}

/* A small drawing of the dial: the brief's sweep, ticks and stepped contour. */
function dialSketch(cv, cx, cy, r, accent) {
    const a0 = -178 + 17.2, a1 = -178 + 172;            /* degrees, the brief's sweep */
    const pt = (deg, rr) => [cx + rr * Math.cos(deg * Math.PI / 180), cy + rr * Math.sin(deg * Math.PI / 180)];
    for (let i = 0; i <= 80; i++) {
        const a = a0 + (a1 - a0) * i / 80;
        const major = i % 10 === 0;
        const p = pt(a, r), q = pt(a, r - (major ? 12 : 6));
        cv.line(p[0], p[1], q[0], q[1], major ? 2 : 1, i > 68 ? RED : (i < 46 ? INK : FAINT));
    }
    let prev = null;
    for (let i = 0; i <= 160; i++) {
        const t = i / 160, v = t * 8, f = v - Math.floor(v);
        const up = Math.max(0, Math.min(1, (f - 0.12) / 0.10)), dn = Math.max(0, Math.min(1, (f - 0.68) / 0.12));
        const p = pt(a0 + (a1 - a0) * t, r * 0.82 + r * 0.027 * (up - dn));
        if (prev) cv.line(prev[0], prev[1], p[0], p[1], 1.5, t > 0.84 ? RED : DIM);
        prev = p;
    }
    const n = pt(a0 + (a1 - a0) * 0.57, r * 0.84), m = pt(a0 + (a1 - a0) * 0.57, r);
    cv.line(n[0], n[1], m[0], m[1], 2.5, accent);
}

/* A small drawing of an M style: the two dials' rails, its middle (the M
   View's centre lines, or M Sport Plus's plate and stripes) and the
   readouts, from the same geometry the cluster is drawn with. */
function mSketch(cv, x, y, w, plus) {
    const s = w / MGeom.ART.w, D = MGeom.DIAL;
    const P = (px, py) => [x + px * s, y + py * s];
    const path = (pts, width, col) => {
        for (let i = 1; i < pts.length; i++) {
            const a = P(pts[i - 1][0], pts[i - 1][1]), b = P(pts[i][0], pts[i][1]);
            cv.line(a[0], a[1], b[0], b[1], width, col);
        }
    };
    const vertex = MGeom.cross(D.rimUp, D.rimLow), bend = MGeom.cross(D.conUp, D.conLow);
    const rim = [[MGeom.at(D.rimUp, D.rimTop), D.rimTop], vertex, [MGeom.at(D.rimLow, D.rimBottom), D.rimBottom]];
    const con = [[D.topX1, D.topY0], [MGeom.at(D.conUp, D.topY0), D.topY0], bend, [MGeom.at(D.conLow, D.conBottom), D.conBottom]];
    const flip = (pts) => pts.map((p) => [MGeom.mirror(p[0]), p[1]]);
    cv.roundRect(x, y, w, MGeom.ART.h * s, 8, '#05070d');
    path(rim, 5, '#8fc6ea'); path(con, 1.5, '#a8cbf0');
    path(flip(rim), 5, '#dc3840'); path(flip(con), 1.5, '#d65458');
    if (plus) {
        const L = MGeom.PLUS, C = L.PLATES.C.v, T = L.STRIPES;
        /* the rails meet in the middle; the centre plate, its two stripes */
        path([[D.tabLeft, D.railTop + 3], [L.RAILS.blueEnd, D.railTop + 3]], 3, '#62b4ea');
        path([[L.RAILS.redStart, D.railTop + 3], [MGeom.mirror(D.tabLeft), D.railTop + 3]], 3, '#d2343c');
        path(C.concat([C[0]]), 1.5, '#3a5f9c');
        const stripe = (b, col) => {
            const m = (b[0] + b[1]) / 2;
            path([[m - L.slope * (L.top + 12), L.top + 12], [m - L.slope * 330, 330]], (b[1] - b[0]) * s * 0.8, col);
        };
        stripe(T.blue, '#418af7');
        stripe(T.red, '#c73847');
    } else {
        path([[D.tabLeft, D.railTop + 3], [MGeom.DIAG.blueRailEnd, D.railTop + 3]], 3, '#62b4ea');
        path([[MGeom.DIAG.redRailStart, D.railTop + 3], [MGeom.mirror(D.tabLeft), D.railTop + 3]], 3, '#d2343c');
        path([MGeom.DIAG.cyan.p0, MGeom.DIAG.cyan.p1, MGeom.DIAG.cyan.p2], 1.5, '#b0d4f4');
        path([MGeom.DIAG.red.p0, MGeom.DIAG.red.p1], 1.5, '#e4485a');
    }
    cv.text('76', x + 520 * s, y + 296 * s, 50 * s * 1.5, INK, { literal: true });
    cv.text('6', x + 1284 * s, y + 296 * s, 50 * s * 1.5, INK, { literal: true });
}

/* A small drawing of M Track Mode: the wing with its bands and gauge rows,
   the plates and the gear between them, the leaning rev counter and the two
   ladders, from the same geometry the cluster is drawn with. */
function tSketch(cv, x, y, w) {
    const A = TGeom.ART, s = w / A.w;
    const P = (px, py) => [x + px * s, y + py * s];
    const path = (pts, width, col, closed) => {
        const q = closed ? pts.concat([pts[0]]) : pts;
        for (let i = 1; i < q.length; i++) {
            const a = P(q[i - 1][0], q[i - 1][1]), b = P(q[i][0], q[i][1]);
            cv.line(a[0], a[1], b[0], b[1], width, col);
        }
    };
    const lean = (u, y0, y1) => [[TGeom.slash(u, y0), y0], [TGeom.slash(u, y1), y1]];
    /* a leaning slab between two "/" lines, from one height to another */
    const slab = (u0, u1, y0, y1, col) => cv.quad([P(TGeom.slash(u0, y0), y0), P(TGeom.slash(u1, y0), y0),
                                                   P(TGeom.slash(u1, y1), y1), P(TGeom.slash(u0, y1), y1)], col);
    cv.roundRect(x, y, w, A.h * s, 8, '#05070d');
    /* two of the M bands, down the wing */
    const B = TGeom.BANDS, top = TGeom.BODY.top + 6;
    slab(B.light.u[0], B.light.u[1], top, 330, '#2f5fd0');
    slab(B.red.u[0], B.red.u[1], top, 330, '#8a3a72');
    /* the wing, the plates either side of the gear, the ribbon */
    path(TGeom.WING.v, 2, '#3a66c8', true);
    ['upper', 'lower', 'ribbon'].forEach((k) => path(TGeom.PLATES[k].v, 2, '#3a66c8', true));
    /* the four gauge rows */
    for (let i = 0; i < TGeom.ROWS.n; i++) {
        const yy = TGeom.rowTop(i) + 2;
        path([[TGeom.ROWS.xs, yy], [TGeom.ROWS.xe, yy]], 2.5, '#eef3f8');
    }
    /* the rev counter: the top line, the contour, the rail, the marker and the lit foot under it */
    const G = TGeom.TACH, yTop = (G.top.y0 + G.top.y1) / 2, ym = TGeom.revMarks()[3];
    path([[G.top.x0, yTop], [TGeom.slash(G.railR, yTop), yTop]], 1.5, '#e08092');
    path(lean(G.con, yTop, ym - 5), 1.5, '#e2a0aa');
    path(lean((G.railL + G.railR) / 2, yTop, ym - 5), Math.max(2, (G.railR - G.railL) * s), '#e64452');
    slab(G.con, G.railR, ym + 6, G.base.foot, '#e84048');
    path([[TGeom.contourX(ym), ym], [TGeom.railX(ym), ym]], 2, '#ffffff');
    /* oil and fuel */
    const S = TGeom.STRIP;
    [S.oil, S.fuel].forEach((at) => path(lean(at + 8, S.top, S.bottom), 3.5, '#9aa3b8'));
    cv.text('4', x + 764 * s, y + 287 * s, 80 * s * 1.42, INK, { literal: true });
    cv.text('76', x + 742 * s, y + 366 * s, 37 * s * 1.42, INK, { literal: true });
}

/*
 * The designs, in the order of their cards on the page (and of the
 * HMI bar's Design button). Each is a style and, for Toro, its background;
 * the colours and everything else stay as set. id: its picture's
 * (previews_data.js).
 */
const DESIGNS = [
    { id: 'toro_genuine', name: 'Toro', card: 'Toro', sub: 'Lamborghini Huracan, genuine', style: 'toro', background: 'genuine' },
    { id: 'toro_modern', name: 'Toro', card: 'Toro hex', sub: 'Lamborghini, modern hex lattice', style: 'toro', background: 'modern' },
    { id: 'toro_revuelto', name: 'Toro', card: 'Toro Revuelto', sub: 'Lamborghini Revuelto', style: 'toro', background: 'revuelto' },
    { id: 'track', name: 'M Sport', card: 'M Sport', sub: 'BMW M View, iDrive 8', style: 'track' },
    { id: 'mplus', name: 'M Sport Plus', card: 'M Sport Plus', sub: 'M stripes, a wide picture in the centre', style: 'mplus' },
    { id: 'mtrack', name: 'M Track Mode', card: 'M Track', sub: 'BMW M\'s track view: four gauges, the gear, a leaning rev counter', style: 'mtrack' }
];
/*
 * Each style's places on the page, as AK Cluster Layouts' readouts: what shows where (the settings of its own
 * group that say so). A place is offered while its setting is (its "when"). The readings' places - the footers, the
 * gauges, the gauge rows and strips - are set here alone ("page": not in the settings list).
 */
const PLACES = {
    toro: ['tCentre', 'tCentreSize', 'gearPlace', 'showBoost', 'showAuxLeft', 'electricGauge', 'modeLabel', 'shiftStyle',
        'gaugeL1', 'gaugeL2', 'gaugeR1', 'gaugeR2'],
    track: ['mCentre', 'mCentreSize', 'mGear', 'mSpeed2', 'mFootL', 'mFootM', 'mFootR', 'mPanel'],
    mplus: ['pCentre', 'pCentreSize', 'pGear', 'pSpeed2', 'pFootL', 'pFootM', 'pFootR', 'pPanel'],
    mtrack: ['kCentre', 'kWing', 'kRow1', 'kRow2', 'kRow3', 'kRow4', 'kStripL', 'kStripR', 'kFootL', 'kFootM', 'kFootR']
};
/* the page's pictures (kit/record.js setImage): the big one, and each design's card (+ its index) */
const IMG_BIG = 0x49443801, IMG_CARD = 0x49443810;
function designIndex(style, background) {
    const i = DESIGNS.findIndex((d) => d.style === style && (d.style !== 'toro' || d.background === background));
    return i < 0 ? 0 : i;
}

const STYLE_NAME = { toro: 'Toro', track: 'M Sport', mplus: 'M Sport Plus', mtrack: 'M Track Mode' };
/* what a style's middle can show, as the short words the buttons carry */
const CENTRE_WORDS = { off: 'Closed', waze: 'Waze', map: 'BMW map', camera: 'Camera', turn: 'Turn card' };
/* M Track Mode's is its left wing, which holds its gauges until a picture is chosen */
const WING_WORDS = Object.assign({}, CENTRE_WORDS, { off: 'Gauges' });

const W = 1600;

mgu.run({
    background(bg) {
        /* (a car chosen under General > Car before it went: its figures into General's, once) */
        try { Panel.moveCarFigures(bg.settings, bg.log); } catch (e) { bg.log.warn('car figures: ' + e); }
        try {
            const svc = Service.start(hostFor(bg), { appId: bg.spec.id });
            bg.log.info('cluster service started');
            return svc;
        } catch (e) {
            bg.log.error('cluster service did not start: ' + (e && e.stack || e));
            return null;
        }
    },

    start(ctx) {
        const { ui, settings, background } = ctx;
        const loop = ctx.loop('MAIN', 4, render);
        let last = '';
        let tab = 'cluster';              /* the page showing: cluster or logs */

        function choice(key) {
            const item = settings.item(key);
            const v = settings.get(key);
            const opt = item && item.options && item.options.find((o) => o[0] === String(v));
            return (opt ? opt[1] : String(v)) + (held(key) ? '  ·  Car profile' : '');
        }
        /* set by the Car profile app (the kit's Settings.held): shown with its value, changed there */
        const held = (key) => !!(settings.held && settings.held(key));
        const style = () => (STYLE_NAME[settings.get('style')] ? settings.get('style') : 'toro');
        /* BETA: how many px lower a style is drawn (0: as it comes) - what was asked, as far as the style goes */
        const lowered = (st) => Math.max(0, Math.min(Math.round(Number(settings.get('lower')) || 0), Theme.lowerMost(st || style())));
        /* the setting a style keeps what shows in its middle under, and what it may be */
        const centreKey = (st) => Theme.keyFor(st || style(), 'centre');
        const centreOptions = (st) => ((settings.item(centreKey(st)) || {}).options || []).map((o) => o[0]);
        const centreOf = (st) => {
            const v = settings.get(centreKey(st));
            return centreOptions(st).indexOf(v) >= 0 ? v : 'off';
        };
        /* a place is offered whatever style is in use: its setting's other conditions still hold */
        function offered(s, onPage) {
            if (!s || (s.hidden && !(onPage && s.page))) return false;
            const w = s.when || {};
            return Object.keys(w).every((k) => k === 'style' || [].concat(w[k]).indexOf(settings.get(k)) >= 0);
        }

        function refresh() { last = ''; loop.kick(); }
        /* Logs: made afresh each time it opens; pressed again, the next page, past the last back to the cluster */
        function logsPressed() {
            if (tab !== 'logs') { logView = null; tab = 'logs'; } else if (logView && (logView.page + 1) * LOG_PER_PAGE < logView.codes.length) logView.page++;
            else tab = 'cluster';
            refresh();
        }
        function toggleShown() { settings.set('enabled', settings.get('enabled') !== true); refresh(); }
        function useDesign(d) {
            settings.set('style', d.style);
            if (d.background) settings.set('background', d.background);
            refresh();
        }
        /*
         * A design's picture at x, y (w x h): handed to the renderer once (kit/record.js setImage), then drawn by its
         * id. False where there is none, or no way to draw one (the design's sketch is drawn instead).
         */
        const sent = {};
        function picture(cv, id, key, px, w, h, x, y) {
            if (!px || !Record || typeof cv.image !== 'function') return false;
            if (sent[id] !== key) { Record.setImage(id, w, h, px); sent[id] = key; }
            cv.image(id, x, y, w, h);
            return true;
        }
        /* the drawing of a design where its picture can't be shown */
        function sketchOf(cv, d, st, x, y, w, h) {
            if (st === 'mtrack') {
                const tw = Math.min(w - 8, (h - 8) * TGeom.ART.w / TGeom.ART.h);
                tSketch(cv, x + (w - tw) / 2, y + (h - tw * TGeom.ART.h / TGeom.ART.w) / 2, tw);
            } else if (st === 'track' || st === 'mplus') {
                const mw = Math.min(w - 8, (h - 8) * MGeom.ART.w / MGeom.ART.h);
                mSketch(cv, x + (w - mw) / 2, y + (h - mw * MGeom.ART.h / MGeom.ART.w) / 2, mw, st === 'mplus');
            } else {
                const r = Math.min(w * 0.42, h - 24);
                dialSketch(cv, x + w / 2, y + h - 12, r, '#ff6a1a');
            }
        }
        /* one setting's values, to pick from: the kit's own list (a sheet over the page) */
        function pick(s) {
            const sh = Sheet.listSheet(settings, s.label);
            const choose = sh.choose.bind(sh);
            sh.open = s;
            sh.sub = Math.max(0, (s.options || []).findIndex((o) => o[0] === String(settings.get(s.key))));
            sh.choose = () => { choose(); return 'close'; };
            sh.back = () => 'close';
            sh.onClose = refresh;
            return sh;
        }
        function press(s) {
            if (!s || held(s.key)) return;
            if (s.type === 'bool') settings.set(s.key, !settings.get(s.key));
            else if (!(ctx.sheet && ctx.sheet(pick(s)))) {
                /* no sheet here: step to the next value */
                const opts = (s.options || []).map((o) => o[0]), i = opts.indexOf(String(settings.get(s.key)));
                if (opts.length) settings.set(s.key, opts[(i + 1) % opts.length]);
            }
            refresh();
        }

        function render() {
            const status = background ? background.status()
                : 'The cluster service did not start - see Logs';
            const on = settings.get('enabled') === true;
            const st = style();
            const track = st === 'track' || st === 'mplus';      /* either M View style */
            const wing = st === 'mtrack';                        /* M Track Mode: its picture is in its left wing */
            const words = wing ? WING_WORDS : CENTRE_WORDS;
            const centre = background && background.centre ? background.centre() : null;
            const feed = background && background.feed ? background.feed() : null;

            useSkin(settings.get('skin'));
            const cv = ctx.canvas(W, 520);
            const H = 520, page = tab;
            const sig = JSON.stringify([status, on, centre, feed, settingsOf(settings, ctx.spec), page, logView && logView.page]);
            if (sig === last) return;
            last = sig;

            /* (o.done: words put together from parts already in the app's language: not looked up again) */
            const inLang = (s, o) => (o && o.done ? String(s) : tr(s));
            const label = (s, x, y, size, c, o) => cv.text(inLang(s, o), x, y, size, c || INK, Object.assign({ literal: true }, o || {}));
            const fitLabel = (s, x, y, size, maxW, c, o) => {
                const w = cv.textWidth(inLang(s, o), size, { literal: true });
                label(String(s), x, y, w > maxW ? size * maxW / w : size, c, o);
            };
            cv.fillRect(0, 0, W, H, BG);

            /* places a finger or the controller can press (nothing here relies on clipping: the head unit's
               software renderer has none) */
            const tgt = (x, y, w, h, run, key, r) => cv.target(x, y, w, h, run, key, r);
            const done = () => ui.image('MAIN_GFX', cv);
            const top = 44, bottom = H - 6, ch = bottom - top;

            if (page === 'logs') { drawLogs(cv, label, fitLabel, tgt, top, ch); return done(); }

            const di = designIndex(settings.get('style'), settings.get('background'));
            const D = DESIGNS[di];
            const PW = Previews.W, PH = Previews.H, TW = Previews.TW, TH = Previews.TH;

            /* ---- left: the design as it looks on the cluster ---- */
            const BX = 24, BY = top + 8;
            cv.roundRect(BX - 4, BY - 4, PW + 8, PH + 8, rad(10), on ? RED : LINE);
            if (!picture(cv, IMG_BIG, D.id, Previews.big(D.id), PW, PH, BX, BY)) {
                cv.fillRect(BX, BY, PW, PH, FIELD);
                sketchOf(cv, D, st, BX, BY, PW, PH);
            }
            if (!on) {
                cv.fillRect(BX, BY, PW, PH, withAlpha('#000000', 0.55));
                label('BMW\'s own cluster shows', BX + PW / 2, BY + PH / 2 + 10, 28, INK, { align: 'center', font: SK7 ? undefined : 'bold' });
            }
            /* under it: the service's state (on / off: the bar's Cluster on / off), and what the centre has to show */
            let y = BY + PH + 14;
            const bw = PW + 8, bh = 56;
            cv.roundRect(BX - 4, y, bw, bh, rad(10), FIELD);
            cv.circle(BX + 26, y + bh / 2, 9, statusColour(status));
            fitLabel(status, BX + 48, y + bh / 2 + 8, 22, bw - 70, INK);
            y += bh + 26;
            const cardsY = bottom - (TH + 46);
            if (y + 18 < cardsY - 8) {
                const tv = centre ? centre.turnView : '-';      /* (most of Turn View's lines name it already) */
                fitLabel(tr('Phone map') + ': ' + tr(centre ? centre.waze : '-') + '   ·   ' + (/^Turn View/.test(tv) ? tr(tv) : 'Turn View: ' + tr(tv)), BX, y, 18, PW, DIM, { done: true });
                if (y + 42 < cardsY - 8) fitLabel(tr('Readings') + ': ' + tr(feed || '-') + '   ·   ' + tr(on ? 'On at every start.' : 'Off: BMW\'s own cluster.'), BX, y + 26, 18, PW, FAINT, { done: true });
            }

            /* ---- right: the design, its state, and what each of its places shows ---- */
            const RX = 664, RW = W - 24 - RX;
            fitLabel(D.name, RX, top + 40, 34, RW - 300, INK, { font: SK7 ? undefined : 'bold' });
            label(lowered(st) ? tr('BMW strip hidden') + ': ' + lowered(st) + ' ' + tr('px lower (BETA)') : tr(status), RX + RW, top + 40, 18,
                statusColour(status), { align: 'right', font: SK7 ? undefined : 'bold', done: true });
            fitLabel(D.sub, RX, top + 68, 18, RW, DIM);
            const keys = (PLACES[st] || []).map((k) => settings.item(k)).filter((s) => s && offered(s, true));
            const COLS = keys.length <= 6 ? 2 : 3, gap = 10;
            const CW = (RW - gap * (COLS - 1)) / COLS, CH = 54;
            const rowsRoom = Math.max(1, Math.floor((cardsY - 12 - (top + 84) + 8) / (CH + 8)));
            keys.slice(0, COLS * rowsRoom).forEach((s, i) => {
                const x = RX + (i % COLS) * (CW + gap), yy = top + 84 + Math.floor(i / COLS) * (CH + 8);
                const isOn = s.type === 'bool' ? !!settings.get(s.key) : null;
                cv.roundRect(x, yy, CW, CH, rad(10), SK7 ? CARD : withAlpha('#ffffff', 0.07));
                if (SK7) cv.fillRect(x, yy + CH - 1, CW, 1, LINE);
                fitLabel(s.label.replace(/\s*\(.*\)$/, ''), x + 16, yy + 20, 14, CW - 30, DIM, { font: SK7 ? undefined : 'bold' });
                const v = s.type === 'bool' ? (isOn ? 'On' : 'Off') : choice(s.key).replace(/ \(.*$/, '');
                fitLabel(v, x + 16, yy + 44, 19, CW - 30, isOn === false ? FAINT : INK, { font: SK7 ? undefined : 'bold' });
                tgt(x, yy, CW, CH, () => press(s), 'place:' + s.key, rad(10));
            });

            /* ---- the designs: a card each, the one in use framed; a tap shows it on the cluster ---- */
            const CWD = Math.floor((W - 48 - (DESIGNS.length - 1) * 12) / DESIGNS.length), CHT = TH + 40;
            DESIGNS.forEach((d, i) => {
                const x = 24 + i * (CWD + 12), mine = i === di;
                if (mine && SK7) focus7(cv, x, cardsY, CWD, CHT);
                else cv.roundRect(x, cardsY, CWD, CHT, rad(10), mine ? RED : CARD);
                cv.roundRect(x + 3, cardsY + 3, CWD - 6, CHT - 6, rad(8), BG);
                const ix = x + Math.round((CWD - TW) / 2), iy = cardsY + 6;
                if (!picture(cv, IMG_CARD + i, d.id + ':card', Previews.thumb(d.id), TW, TH, ix, iy)) {
                    cv.fillRect(ix, iy, TW, TH, FIELD);
                    sketchOf(cv, d, d.style, ix, iy, TW, TH);
                }
                fitLabel(d.card, x + CWD / 2, cardsY + CHT - 10, 18, CWD - 16, mine ? '#ffffff' : INK, { align: 'center', font: SK7 ? undefined : 'bold' });
                tgt(x, cardsY, CWD, CHT, () => useDesign(d), 'design:' + d.id, rad(10));
            });
            return done();
        }

        /*
         * LOGS: what's needed to find a problem, as AK Cluster Layouts' Logs gathers it - QR codes to photograph,
         * three a page (tools/decode_logs.py puts them back together), and the whole as a file in the app's data folder
         * and on a USB stick. Made when Logs opens and at Make again.
         */
        let logView = null;      /* { codes, page, saved } */
        const LOG_PER_PAGE = 3;
        function logBundle(full) {
            const snap = background && background.snapshot ? background.snapshot() : { status: 'the cluster service did not start' };
            const n = (short, long) => (full ? long : short);
            return Logs.bundle(String(ctx.spec.title || 'AK Cluster ID8') + ' ' + String(ctx.spec.version || ''), [
                ['settings', JSON.stringify(settingsOf(settings, ctx.spec))],
                ['service', JSON.stringify({ status: snap.status, running: snap.running, connected: snap.connected, profile: snap.profile,
                    style: snap.style, electric: snap.electric, phevFound: snap.phevFound })],
                ['readings from', String((background && background.feed && background.feed()) || '-')],
                ['engine unit', JSON.stringify({ needs: snap.needs, engine: snap.engine })],
                ['centre', JSON.stringify((background && background.centre && background.centre()) || null)],
                ['data now', JSON.stringify(snap.readings || {})],
                ['cluster-render log', Logs.tail(Logs.RENDER_LOG, n(20, 1500))],
                ['this app\'s log', Logs.tail(path.join(ctx.dataDir || '.', String(ctx.spec.id) + '.log'), n(40, 600))]
            ]);
        }
        function makeLogs() {
            const log = ctx.log || { info() {}, warn() {} };
            let saved = [];
            try {
                saved = Logs.save(logBundle(true), ctx.dataDir, 'cluster-logs-id8-' + new Date().toISOString().replace(/[:.]/g, '-') + '.txt');
                saved.forEach((r) => log.info('logs: ' + (r.file ? 'saved ' + r.file : r.dir + ': ' + r.error)));
            } catch (e) { log.warn('logs: ' + e); }
            let codes = [];
            try { codes = Logs.codes(logBundle(false)).codes; } catch (e) { log.warn('logs: ' + e); }
            logView = { codes, page: 0, saved };
        }
        function drawLogs(cv, label, fitLabel, tgt, top, ch) {
            if (!logView) makeLogs();
            const n = logView.codes.length, pages = Math.max(1, Math.ceil(n / LOG_PER_PAGE));
            logView.page = Math.min(logView.page, pages - 1);
            const first = logView.page * LOG_PER_PAGE;
            const usb = logView.saved.filter((r) => r.file && !/exports/.test(r.file));
            fitLabel(tr('Photograph each code') + '  ·  ' + tr('page') + ' ' + (logView.page + 1) + ' / ' + pages + '  ·  ' + tr('codes') + ' ' +
                (n ? (first + 1) + '-' + Math.min(n, first + LOG_PER_PAGE) : '0') + ' / ' + n, 30, top + 30, 21, 900, INK, { done: true });
            fitLabel(usb.length ? tr('The full logs are also on the USB stick:') + ' ' + usb[0].file
                : tr('Plug in a USB stick and press Make again for the full logs as a file'), 30, top + 58, 16, 900, DIM, { done: true });
            /* the page's buttons, right of those lines */
            const btn = (x, w, word, run, key, on) => {
                if (on && SK7) focus7(cv, x, top + 4, w, 46);
                else cv.roundRect(x, top + 4, w, 46, rad(23), on ? RED : CARD);
                label(SK7 ? word : word.toUpperCase(), x + w / 2, top + 35, SK7 ? 21 : 18, on ? '#ffffff' : INK,
                    SK7 ? { align: 'center' } : { align: 'center', font: 'bold', spacing: 1 });
                tgt(x, top + 4, w, 46, run, key, rad(23));
            };
            btn(W - 600, 180, 'Previous', () => { logView.page = Math.max(0, logView.page - 1); refresh(); }, 'logs:prev', false);
            btn(W - 410, 180, 'Next', () => { logView.page = (logView.page + 1) % pages; refresh(); }, 'logs:next', true);
            btn(W - 220, 196, 'Make again', () => { makeLogs(); refresh(); }, 'logs:make', false);
            const cy = top + 84, room = Math.max(120, top + ch - cy - 30);
            logView.codes.slice(first, first + LOG_PER_PAGE).forEach((q, i) => {
                const px = Math.max(2, Math.floor(Math.min(420, room) / (q.size + 8)));
                const side = (q.size + 8) * px, x = 40 + i * 520;
                Logs.draw(cv, q, x, cy, px);
                label(String(first + i + 1) + ' / ' + n, x + side / 2, cy + side + 22, 18, INK, { align: 'center', font: SK7 ? undefined : 'bold', done: true });
            });
            if (!n) label('Nothing to show yet', 30, cy + 40, 22, DIM);
        }

        settings.onChange(refresh);
        ctx.onLayout(refresh);
        ui.onVisible((name) => { if (name === 'MAIN') refresh(); });

        ui.onClick('BTN_SHOW', toggleShown);
        ui.onClick('BTN_LOGS', logsPressed);
        /* the controller pushed left with nothing further left on Logs: back to the page (on the page: the kit's, it leaves) */
        if (ctx.onBack) ctx.onBack((edge) => { if (!edge || tab !== 'logs') return false; tab = 'cluster'; refresh(); return true; });
        refresh();
    }
});
